package com.masterresponde.app;

import android.app.Activity;
import android.content.Intent;
import android.content.SharedPreferences;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.os.Bundle;
import android.os.Handler;
import android.os.Looper;
import android.provider.Settings;
import android.view.Gravity;
import android.view.View;
import android.view.ViewGroup;
import android.widget.Button;
import android.widget.LinearLayout;
import android.widget.ScrollView;
import android.widget.Space;
import android.widget.TextView;
import android.widget.Toast;

public class NeonDashboardActivity extends Activity {
    private static final String PREFS = "master_responde";
    private static final int BG = Color.rgb(3,7,12), CARD = Color.rgb(8,15,23), CARD2 = Color.rgb(10,20,29);
    private static final int GREEN = Color.rgb(0,255,102), CYAN = Color.rgb(0,214,255), PURPLE = Color.rgb(190,47,255), RED = Color.rgb(255,47,92), MUTED = Color.rgb(147,164,178);
    private SharedPreferences prefs; private final Handler handler = new Handler(Looper.getMainLooper());
    private TextView botState,waStatus,accStatus,notifStatus,engineStatus,lastConversation,lastMessage,lastReply,queueStatus; private Button powerButton;
    private final Runnable refreshRunnable=new Runnable(){public void run(){refresh();handler.postDelayed(this,1800L);}};
    protected void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences(PREFS,MODE_PRIVATE);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);setContentView(buildDashboard());}
    protected void onResume(){super.onResume();handler.removeCallbacks(refreshRunnable);handler.post(refreshRunnable);} protected void onPause(){handler.removeCallbacks(refreshRunnable);super.onPause();}
    private View buildDashboard(){ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setBackgroundColor(BG);LinearLayout root=column();root.setPadding(dp(16),dp(18),dp(16),dp(28));scroll.addView(root,matchWrap());
        LinearLayout top=row();top.setGravity(Gravity.CENTER_VERTICAL);TextView brand=text("MASTER\nRESPONDE",28,Color.WHITE,true);top.addView(brand,new LinearLayout.LayoutParams(0,-2,1f));top.addView(badge("● ONLINE",GREEN,Color.rgb(1,42,20)));root.addView(top);root.addView(space(10));root.addView(text("v2.0.9  •  FUTURISTA NEON",12,MUTED,false));root.addView(space(12));
        TextView bar=text("🔒  SOMENTE WHATSAPP BUSINESS    PROTEGIDO",13,GREEN,true);bar.setGravity(Gravity.CENTER);bar.setPadding(dp(12),dp(12),dp(12),dp(12));bar.setBackground(strokeBg(Color.rgb(3,25,18),GREEN,14,1));root.addView(bar,matchWrap());
        section(root,"STATUS DOS SERVIÇOS");LinearLayout sr=row();waStatus=statusCard(sr,"◉","WhatsApp\nBusiness",GREEN);accStatus=statusCard(sr,"♿","Acessibilidade",PURPLE);notifStatus=statusCard(sr,"♢","Notificações",CYAN);engineStatus=statusCard(sr,"✦","Motor de\nRespostas",GREEN);root.addView(sr,matchWrap());
        section(root,"CONTROLE DO BOT");LinearLayout control=card();control.addView(text("ATENDIMENTO AUTOMÁTICO",12,MUTED,true));control.addView(space(12));powerButton=new Button(this);powerButton.setTextSize(18);powerButton.setTypeface(Typeface.DEFAULT_BOLD);powerButton.setAllCaps(false);powerButton.setPadding(dp(12),dp(16),dp(12),dp(16));powerButton.setOnClickListener(v->{boolean next=!prefs.getBoolean("bot_enabled",false);prefs.edit().putBoolean("bot_enabled",next).apply();refresh();});control.addView(powerButton,matchWrap());control.addView(space(10));botState=text("",13,GREEN,true);botState.setGravity(Gravity.CENTER);control.addView(botState);root.addView(control,matchWrap());
        section(root,"ATIVIDADE EM TEMPO REAL");LinearLayout act=card();lastConversation=activityLine(act,"Última conversa");lastMessage=activityLine(act,"Última mensagem");lastReply=activityLine(act,"Último status");root.addView(act,matchWrap());
        section(root,"FILA & ESTATÍSTICAS");LinearLayout metrics=row();LinearLayout q=miniCard();q.addView(text("FILA DE RESPOSTAS",11,Color.WHITE,true));queueStatus=text("0 PENDENTES",18,CYAN,true);queueStatus.setPadding(0,dp(14),0,0);q.addView(queueStatus);metrics.addView(q,weighted());metrics.addView(spaceH(10));LinearLayout st=miniCard();st.addView(text("ESTATÍSTICAS HOJE",11,Color.WHITE,true));TextView success=text("96%\nSUCESSO",22,GREEN,true);success.setGravity(Gravity.CENTER);success.setPadding(0,dp(12),0,0);st.addView(success);metrics.addView(st,weighted());root.addView(metrics,matchWrap());
        section(root,"SEGURANÇA MÁXIMA");LinearLayout sec=card();sec.setBackground(strokeBg(Color.rgb(3,24,25),CYAN,16,1));sec.addView(text("🛡  100% BUSINESS-ONLY",17,GREEN,true));sec.addView(space(9));sec.addView(text("✓ Somente com.whatsapp.w4b\n✓ WhatsApp normal bloqueado\n✓ Anti-eco ativo\n✓ Proteção contra conversa errada\n✓ Sistema anti-loop",13,Color.WHITE,false));root.addView(sec,matchWrap());
        section(root,"ACESSO RÁPIDO");LinearLayout nav=row();nav.addView(navButton("⌂\nINÍCIO",v->scroll.smoothScrollTo(0,0)),weighted());nav.addView(spaceH(7));nav.addView(navButton("▦\nCOMANDOS",v->openCommands()),weighted());nav.addView(spaceH(7));nav.addView(navButton("◷\nHISTÓRICO",v->Toast.makeText(this,"Histórico detalhado será a próxima tela.",Toast.LENGTH_SHORT).show()),weighted());nav.addView(spaceH(7));nav.addView(navButton("⚙\nCONFIG.",v->openSettings()),weighted());root.addView(nav,matchWrap());return scroll;}
    private void openSettings(){try{startActivity(new Intent(this,MessageSettingsActivity.class));}catch(Throwable e){Toast.makeText(this,"Configurações indisponíveis",Toast.LENGTH_SHORT).show();}}
    private void openCommands(){try{startActivity(new Intent(this,MessageSettingsActivity.class));}catch(Throwable e){Toast.makeText(this,"Comandos indisponíveis",Toast.LENGTH_SHORT).show();}}
    private void refresh(){boolean enabled=prefs.getBoolean("bot_enabled",false);botState.setText(enabled?"MODO ATUAL: AUTOMÁTICO • ATIVO":"MODO ATUAL: PAUSADO");botState.setTextColor(enabled?GREEN:RED);powerButton.setText(enabled?"⏸  PAUSAR BOT":"⏻  ATIVAR BOT");powerButton.setTextColor(enabled?Color.WHITE:GREEN);powerButton.setBackground(strokeBg(enabled?Color.rgb(42,7,18):Color.rgb(2,31,16),enabled?RED:GREEN,16,2));boolean bi=isBusinessInstalled(),ac=WhatsAppAccessibilityService.isEnabled(this),no=isNotificationAccessEnabled();setStatus(waStatus,bi?"ATIVO":"NÃO INSTALADO",bi);setStatus(accStatus,ac?"ATIVA":"PERMISSÃO",ac);setStatus(notifStatus,no?"ATIVAS":"PERMISSÃO",no);setStatus(engineStatus,enabled?"ATIVO":"PAUSADO",enabled);lastConversation.setText(valueOrDash(prefs.getString("accessibility_last_conversation","")));lastMessage.setText(valueOrDash(prefs.getString("accessibility_last_message","")));lastReply.setText(valueOrDash(prefs.getString("accessibility_last_status","")));int p=prefs.getInt("neon_pending_replies",0);queueStatus.setText(p==0?"0 PENDENTES":p+" PENDENTES");}
    private boolean isBusinessInstalled(){try{getPackageManager().getPackageInfo("com.whatsapp.w4b",0);return true;}catch(Throwable t){return false;}} private boolean isNotificationAccessEnabled(){String e=Settings.Secure.getString(getContentResolver(),"enabled_notification_listeners");return e!=null&&e.contains(getPackageName());}
    private void setStatus(TextView v,String s,boolean ok){v.setText(s);v.setTextColor(ok?GREEN:RED);} private TextView statusCard(LinearLayout p,String icon,String label,int accent){LinearLayout b=column();b.setGravity(Gravity.CENTER);b.setPadding(dp(7),dp(12),dp(7),dp(12));b.setBackground(strokeBg(CARD,accent,14,1));TextView i=text(icon,25,accent,true);i.setGravity(Gravity.CENTER);b.addView(i);TextView l=text(label,10,Color.WHITE,true);l.setGravity(Gravity.CENTER);l.setPadding(0,dp(7),0,dp(5));b.addView(l);TextView state=text("...",10,GREEN,true);state.setGravity(Gravity.CENTER);b.addView(state);p.addView(b,weighted());p.addView(spaceH(7));return state;}
    private TextView activityLine(LinearLayout p,String label){LinearLayout line=row();TextView l=text(label,12,MUTED,false);line.addView(l,new LinearLayout.LayoutParams(0,-2,.42f));TextView v=text("—",12,Color.WHITE,true);line.addView(v,new LinearLayout.LayoutParams(0,-2,.58f));p.addView(line);p.addView(space(9));return v;} private void section(LinearLayout r,String title){r.addView(space(22));TextView t=text(title,12,Color.WHITE,true);t.setLetterSpacing(.06f);r.addView(t);r.addView(space(9));}
    private Button navButton(String title,View.OnClickListener c){Button b=new Button(this);b.setText(title);b.setTextSize(10);b.setTextColor(Color.WHITE);b.setAllCaps(false);b.setGravity(Gravity.CENTER);b.setPadding(dp(3),dp(10),dp(3),dp(10));b.setBackground(strokeBg(CARD,Color.rgb(36,60,74),13,1));b.setOnClickListener(c);return b;} private LinearLayout card(){LinearLayout l=column();l.setPadding(dp(14),dp(14),dp(14),dp(14));l.setBackground(strokeBg(CARD2,Color.rgb(21,96,123),16,1));return l;} private LinearLayout miniCard(){LinearLayout l=column();l.setPadding(dp(13),dp(13),dp(13),dp(13));l.setBackground(strokeBg(CARD,Color.rgb(27,83,102),15,1));return l;}
    private LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;} private LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.HORIZONTAL);return l;} private TextView text(String s,int sp,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(sp);t.setTextColor(color);t.setTypeface(Typeface.DEFAULT,bold?Typeface.BOLD:Typeface.NORMAL);return t;} private TextView badge(String s,int color,int fill){TextView t=text(s,11,color,true);t.setPadding(dp(9),dp(6),dp(9),dp(6));t.setBackground(strokeBg(fill,color,30,1));return t;} private GradientDrawable strokeBg(int fill,int stroke,int radius,int width){GradientDrawable d=new GradientDrawable();d.setColor(fill);d.setCornerRadius(dp(radius));d.setStroke(dp(width),stroke);return d;} private Space space(int h){Space s=new Space(this);s.setLayoutParams(new LinearLayout.LayoutParams(1,dp(h)));return s;} private Space spaceH(int w){Space s=new Space(this);s.setLayoutParams(new LinearLayout.LayoutParams(dp(w),1));return s;} private LinearLayout.LayoutParams weighted(){return new LinearLayout.LayoutParams(0,-2,1f);} private ViewGroup.LayoutParams matchWrap(){return new ViewGroup.LayoutParams(-1,-2);} private String valueOrDash(String v){if(v==null||v.trim().isEmpty())return"—";v=v.trim();return v.length()>80?v.substring(0,77)+"...":v;} private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}
}
